function consolidateCommitteeHistory(sessions=[]){const groups=new Map(),idMap=new Map();let changed=false;for(const original of sessions){const term=String(original.term||'').trim().replace(/[–—−]/g,'-').replace(/\s+/g,' ').toLocaleLowerCase();if(!term){const standalone={...original,members:[...(original.members||[])]};groups.set(Symbol(),standalone);idMap.set(original.id,original.id);continue}let merged=groups.get(term);if(!merged){merged={...original,members:[]};groups.set(term,merged)}else changed=true;idMap.set(original.id,merged.id);for(const member of original.members||[]){const key=[member.position,member.name].map(x=>String(x||'').trim().toLocaleLowerCase()).join('|');const existing=merged.members.find(m=>[m.position,m.name].map(x=>String(x||'').trim().toLocaleLowerCase()).join('|')===key);if(!existing)merged.members.push({...member});else{changed=true;for(const [field,value] of Object.entries(member))if((existing[field]===undefined||existing[field]==='')&&value!=='')existing[field]=value}}if(String(original.archivedAt||'')>String(merged.archivedAt||''))merged.archivedAt=original.archivedAt}const result=[...groups.values()].map(session=>session);return {sessions:result,idMap,changed}}
