function emailContactLink(email,name=''){if(!email)return '';let token=crypto.randomUUID();emailTargets.set(token,String(email));return `<a class="phone-icon-link email-link" href="#email" data-email-token="${token}" aria-label="E-mel ${esc(name)}" title="E-mel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5.5h18A1.5 1.5 0 0 1 22.5 7v10a1.5 1.5 0 0 1-1.5 1.5H3A1.5 1.5 0 0 1 1.5 17V7A1.5 1.5 0 0 1 3 5.5Zm-.2 2 9.2 6.2 9.2-6.2"/></svg></a>`}
