data.households??=seed.households;data.polls??=seed.polls;data.committee??=seed.committee;data.committeeRoles??=seed.committeeRoles;data.committeeHistory??=[];data.lastCommitteeSessionUndo??=null;let committeeHistoryMerge=consolidateCommitteeHistory(data.committeeHistory);data.committeeHistory=committeeHistoryMerge.sessions;if(data.lastCommitteeSessionUndo?.archiveId)data.lastCommitteeSessionUndo.archiveId=committeeHistoryMerge.idMap.get(data.lastCommitteeSessionUndo.archiveId)||data.lastCommitteeSessionUndo.archiveId;data.committeeRolePhones??={};data.committeeTerm??="2026 – 2028";data.residentNotices??=[];data.auditLogs??=[];data.residentBlocks??=seed.residentBlocks;data.committee.forEach(m=>{if(!data.committeeRoles.includes(m.position))data.committeeRoles.push(m.position);let n=String(m.unit||'').match(/\d+/);if(n)m.unit=String(Number(n[0]))});data.households.forEach(h=>{let n=String(h.unit||'').match(/\d+/);if(n)h.unit=String(Number(n[0]));h.members??=[];h.members=h.members.map(m=>typeof m==='string'?{name:m,ageAtYear:null,ageRecordedYear:currentYear}:m);let demo=seed.households.find(x=>x.id===h.id&&x.head===h.head&&Number(x.unit)===Number(h.unit));if(demo){h.headAgeAtYear??=demo.headAgeAtYear;h.headAgeRecordedYear??=demo.headAgeRecordedYear;h.members.forEach(m=>{let sample=demo.members.find(x=>x.name===m.name);if(sample){m.ageAtYear??=sample.ageAtYear;m.ageRecordedYear??=sample.ageRecordedYear}})}});data.committee.forEach(m=>{m.name=cleanAjkName(m.name)});data.committeeHistory.forEach(session=>(session.members||[]).forEach(m=>{m.name=cleanAjkName(m.name)}));data.residentBlocks.forEach(b=>{b.members=Array.isArray(b.members)?b.members:[]});data.polls.forEach(p=>p.votes??={});
