const richTextTags=new Set(['p','br','strong','b','em','i','u','ul','ol','li','blockquote','a']);
function sanitizeRichHtml(input=''){const doc=new DOMParser().parseFromString('<div>'+String(input||'')+'</div>','text/html'),root=doc.body.firstChild;function clean(node){if(node.nodeType===3)return esc(node.nodeValue).replace(/\r?\n/g,'<br>');if(node.nodeType!==1)return '';let tag=node.tagName.toLowerCase(),children=[...node.childNodes].map(clean).join('');if(tag==='br')return '<br>';if(tag==='div')return '<p>'+children+'</p>';if(!richTextTags.has(tag))return children;if(tag==='a'){let href=node.getAttribute('href')||'';if(!/^(https?:\/\/|mailto:)/i.test(href))return children;return '<a href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+children+'</a>'}return '<'+tag+'>'+children+'</'+tag+'>'}return [...root.childNodes].map(clean).join('')}
