async function committeePhotoData(file){if(!file.type.startsWith('image/'))throw new Error('Pilih fail gambar yang sah');if(file.size>12*1024*1024)throw new Error('Saiz gambar maksimum ialah 12 MB');let source=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Gambar tidak dapat dibaca'));reader.readAsDataURL(file)});let img=new Image();img.src=source;await img.decode();let scale=Math.min(1,720/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82)}


