function auditRecordName(type,r={}){if(type==='resident')return `Rumah ${r.number||''}${r.head?' · '+r.head:''}`;if(type==='household')return `Rumah ${r.unit||''}${r.head?' · '+r.head:''}`;if(type==='committee')return `${r.name||'AJK'}${r.position?' · '+r.position:''}`;if(type==='committeeHistory')return r.term||'Arkib AJK';if(type==='committeeRole')return r.roleName||'Jawatan AJK';return r.title||r.question||r.term||auditTypes[type]||'Rekod'}
function auditChangedFields(before,after){let keys=new Set([...Object.keys(before||{}),...Object.keys(after||{})]);return [...keys].filter(k=>!['id','createdAt','updatedAt','publishedAt','archivedAt','votes','going','contactPhone'].includes(k)&&JSON.stringify(before?.[k])!==JSON.stringify(after?.[k])).map(k=>auditFields[k]||k)}
function auditAddedFields(record){return Object.keys(record||{}).filter(k=>!['id','createdAt','updatedAt','publishedAt','archivedAt','votes','going','photo','phone','email'].includes(k)&&record[k]!==''&&record[k]!==undefined).map(k=>auditFields[k]||k)}
