async function loadCommitteeCandidates(editingId=null){const role=window.COMMUNITY_SESSION?.profile.role;if(!['admin','ajk'].includes(role))return false;let {data:rows,error}=await window.COMMUNITY_SUPABASE.rpc('list_managed_accounts');if(error){toast('Senarai pengguna tidak dapat dimuatkan. Pastikan migration pengurusan akaun sudah dijalankan.');return false}committeeCandidates=(Array.isArray(rows)?rows:[]).filter(row=>{if(row.approval_status!=='approved'||!['ajk','bendahari','admin'].includes(row.role)||!row.full_name||!row.house_number)return false;let unit=Number(row.house_number),household=data.households.find(item=>Number(item.unit)===unit),block=data.residentBlocks.find(item=>Number(item.number)===unit);if(!household?.head?.trim()||block?.status!=='updated'||!block.head?.trim())return false;return !data.committee.some(member=>member.id!==editingId&&(String(member.accountUserId||'')===String(row.user_id)||String(member.name||'').trim().toLocaleLowerCase()===String(row.full_name).trim().toLocaleLowerCase()&&(!member.unit||Number(member.unit)===unit))) });return true}
