const ageFromDateOfBirth=dob=>{if(!dob)return null;let birth=new Date(String(dob)+'T00:00:00');if(!Number.isFinite(birth.getTime()))return null;let today=new Date(),age=today.getFullYear()-birth.getFullYear();if(today.getMonth()<birth.getMonth()||(today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate()))age--;return age>=0?age:null};
